import{_ as a}from"./chunks/Ollama-密钥.BwN44ViN.js";import{_ as r}from"./chunks/通义千问-聊天模型-私有.CuBIdYkO.js";import{_ as t,o as p,c as l,a2 as i}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/DeepSeek-%E5%AE%98%E6%96%B9.CLrrUFhT.png",_=JSON.parse('{"title":"【模型接入】DeepSeek","description":"","frontmatter":{},"headers":[],"relativePath":"ai/deep-seek.md","filePath":"ai/deep-seek.md","lastUpdated":null}'),o={name:"ai/deep-seek.md"};function d(n,e,h,k,c,m){return p(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="【模型接入】deepseek" tabindex="-1">【模型接入】DeepSeek <a class="header-anchor" href="#【模型接入】deepseek" aria-label="Permalink to &quot;【模型接入】DeepSeek&quot;">​</a></h1><p>项目基于 Spring AI 提供的 <a href="https://github.com/spring-projects/spring-ai/tree/main/models/spring-ai-deepseek" target="_blank" rel="noreferrer"><code>spring-ai-deepseek</code></a> ，实现 DeepSeek 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>deepseek-v4-flash、deepseek-v4-pro</td><td>DeepSeekChatModel</td></tr><tr><td>AI 绘画</td><td>Janus-Pro</td><td>暂不支持</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>DeepSeek 目前有 3 种方式，可以进行使用：</p><p>① 方式一：官方 API：DeepSeek 提供官方 API 服务，并且价格非常便宜，一般建议直接采用这种方式使用。</p><p>② 方式二：私有化部署：<a href="https://github.com/deepseek-ai" target="_blank" rel="noreferrer">DeepSeek</a> 有开源模型，所以可以本地私有化部署使用。</p><p>③ 方式三：云厂商部署：类似阿里云、字节、腾讯等厂商，私有化部署了 DeepSeek，然后提供 API 服务。</p><h3 id="_1-1-方式一-官方-api-申请" tabindex="-1">1.1 方式一：官方 API 申请 <a class="header-anchor" href="#_1-1-方式一-官方-api-申请" aria-label="Permalink to &quot;1.1 方式一：官方 API 申请&quot;">​</a></h3><p>① 在 <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek 开放平台</a> 上，注册一个账号。目前，默认注册就送 500w tokens，还是蛮爽的。</p><p>② 在 <a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">API keys</a> 菜单，创建一个 API key 即可。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+s+'" alt="官方的密钥配置"></p><h3 id="_1-2-方式二-私有化部署" tabindex="-1">1.2 方式二：私有化部署 <a class="header-anchor" href="#_1-2-方式二-私有化部署" aria-label="Permalink to &quot;1.2 方式二：私有化部署&quot;">​</a></h3><p>友情提示：</p><p>由于 DeepSeek V4 模型尺寸比较大，Ollama 暂未提供本地部署的官方方案。当然，感兴趣也可以试试社区模型 <a href="https://ollama.com/munoz_danilo/deepseek-v4-flash" target="_blank" rel="noreferrer">deepseek-v4-flash</a> 。</p><p>所以下面仍然使用 <code>deepseek-r1</code> 作为本地私有化部署示例。</p><p>① 访问 <a href="https://ollama.ai/download" target="_blank" rel="noreferrer">https://ollama.ai/download</a>，下载对应系统 Ollama 客户端，然后安装。</p><p>② 安装完成后，在命令中执行 <code>ollama run deepseek-r1</code> 命令，一键部署 <a href="https://ollama.com/library/deepseek-r1" target="_blank" rel="noreferrer">deepseek-r1 开源模型</a> ，默认跑的是 <code>deepseek-r1:7b</code> 模型。</p><hr><p>部署完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。需要填写“密钥” + “自定义 API URL”（因为让 Spring AI 使用该地址）。如下图所示：</p><p><img src="'+a+'" alt="私有的密钥配置"></p><p>如果想部署 deepseek 的其它模型，可以搜索 <a href="https://ollama.com/search?q=deepseek" target="_blank" rel="noreferrer">deepseek</a> 文档，执行不同的 <code>ollama run</code> 命令即可。</p><p>注意：使用该方式时，后续配置模型名时，需要使用 <code>deepseek-r1</code> 而不是 <code>deepseek-reasoner</code>！！！例如说：</p><p><img src="'+r+`" alt="私有的聊天模型"></p><h3 id="_1-3-方式三-云厂商部署" tabindex="-1">1.3 方式三：云厂商部署 <a class="header-anchor" href="#_1-3-方式三-云厂商部署" aria-label="Permalink to &quot;1.3 方式三：云厂商部署&quot;">​</a></h3><p>参见「3. 云厂商部署」小节。</p><p>一般建议先通过方式一或方式二跑通，再考虑使用方式三哈。</p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>模型有：<code>deepseek-v4-flash</code>、<code>deepseek-v4-pro</code>，可通过 <a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">《DeepSeek API 文档》</a> 查看。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>deepseek-v4-flash</code></td><td>65536</td></tr><tr><td><code>deepseek-v4-pro</code></td><td>384000</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 DeepSeek ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 DeepSeekChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>spring.ai.deepseek</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    deepseek</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># DeepSeek</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${DEEPSEEK_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-v4-flash</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，DeepSeekChatModelTests 里有对应的测试用例，可以参考。</p><h2 id="_4-云厂商部署" tabindex="-1">4. 云厂商部署 <a class="header-anchor" href="#_4-云厂商部署" aria-label="Permalink to &quot;4. 云厂商部署&quot;">​</a></h2><p>除了 DeepSeek 官方 API，也可以通过云厂商部署的 DeepSeek 模型接入。不同厂商的 API URL、模型标识、thinking 返回格式可能不同，建议优先按厂商文档填写“自定义 API URL”和模型标识。</p><h3 id="_4-1-阿里云-api" tabindex="-1">4.1 阿里云 API <a class="header-anchor" href="#_4-1-阿里云-api" aria-label="Permalink to &quot;4.1 阿里云 API&quot;">​</a></h3><p>① 参考 <a href="./tongyi">《【模型接入】通义千问》</a> 文档，申请阿里云密钥，并配置 API 密钥。</p><p>② 配置聊天模型时，字段可以按下面填写：</p><ul><li>所属平台：<code>TongYi</code></li><li>模型标识：<code>deepseek-v4-pro</code> 或 <code>deepseek-v4-flash</code></li><li>API 密钥：选择前面配置的阿里云密钥</li></ul><p>具体模型可见阿里云百炼的 <a href="https://bailian.console.aliyun.com/cn-beijing#/model-market/detail/deepseek-v4-pro" target="_blank" rel="noreferrer">deepseek-v4-pro</a> 和 <a href="https://bailian.console.aliyun.com/cn-beijing#/model-market/detail/deepseek-v4-flash" target="_blank" rel="noreferrer">deepseek-v4-flash</a> 。</p><h3 id="_4-2-腾讯云-api" tabindex="-1">4.2 腾讯云 API <a class="header-anchor" href="#_4-2-腾讯云-api" aria-label="Permalink to &quot;4.2 腾讯云 API&quot;">​</a></h3><p>① 如果使用腾讯云 TokenHub，可以参考 <a href="./hunyuan">《【模型接入】腾讯混元》</a> 文档，申请腾讯 API Key，并配置 API 密钥。</p><p>② 配置聊天模型时，字段可以按下面填写：</p><ul><li>所属平台：<code>HunYuan</code></li><li>模型标识：<code>deepseek-v4-flash</code> 或 <code>deepseek-v4-pro</code></li><li>API 密钥：选择前面配置的腾讯混元密钥</li></ul><p>具体模型可见腾讯云 TokenHub 的 <a href="https://console.cloud.tencent.com/tokenhub/models/detail?modelId=deepseek-v4-flash&amp;regionId=1&amp;from=all" target="_blank" rel="noreferrer">deepseek-v4-flash</a> 和 <a href="https://console.cloud.tencent.com/tokenhub/models/detail?modelId=deepseek-v4-pro&amp;regionId=1&amp;from=all" target="_blank" rel="noreferrer">deepseek-v4-pro</a> 。</p><h3 id="_4-3-字节火山云-api" tabindex="-1">4.3 字节火山云 API <a class="header-anchor" href="#_4-3-字节火山云-api" aria-label="Permalink to &quot;4.3 字节火山云 API&quot;">​</a></h3><p>① 参考 <a href="./doubao">《【模型接入】字节豆包》</a> 文档，申请字节密钥，并配置 API 密钥。</p><p>② 配置聊天模型时，字段可以按下面填写：</p><ul><li>所属平台：<code>DouBao</code></li><li>模型标识：<code>deepseek-v4-pro-260425</code> 或 <code>deepseek-v4-flash-260425</code></li><li>API 密钥：选择前面配置的字节豆包密钥</li></ul><p>具体模型可见火山方舟的 <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/model/detail?Id=deepseek-v4-pro" target="_blank" rel="noreferrer">deepseek-v4-pro</a> 和 <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/model/detail?Id=deepseek-v4-flash" target="_blank" rel="noreferrer">deepseek-v4-flash</a> 。</p><h3 id="_4-4-百度-api" tabindex="-1">4.4 百度 API <a class="header-anchor" href="#_4-4-百度-api" aria-label="Permalink to &quot;4.4 百度 API&quot;">​</a></h3><p>① 参考 <a href="./yiyan">《【模型接入】文心一言》</a> 文档，申请百度千帆密钥，并配置 API 密钥。</p><p>② 配置聊天模型时，字段可以按下面填写：</p><ul><li>所属平台：<code>YiYan</code></li><li>模型标识：<code>deepseek-v4-pro</code> 或 <code>deepseek-v4-flash</code></li><li>API 密钥：选择前面配置的百度千帆密钥</li></ul><p>具体模型可见百度千帆的 <a href="https://console.bce.baidu.com/qianfan/modelcenter/model/buildIn/detail/am-ef6aeca66ed0?tab=version#DeepSeek-V4-Pro" target="_blank" rel="noreferrer">DeepSeek-V4-Pro</a> 和 <a href="https://console.bce.baidu.com/qianfan/modelcenter/model/buildIn/detail/am-c22b1beec35b" target="_blank" rel="noreferrer">DeepSeek-V4-Flash</a> 。</p><h3 id="_4-5-硅基流动-api" tabindex="-1">4.5 硅基流动 API <a class="header-anchor" href="#_4-5-硅基流动-api" aria-label="Permalink to &quot;4.5 硅基流动 API&quot;">​</a></h3><p>① 参考 <a href="./siliconflow">《【模型接入】硅基流动》</a> 文档，申请硅基密钥，并配置 API 密钥。</p><p>② 配置聊天模型时，字段可以按下面填写：</p><ul><li>所属平台：<code>SiliconFlow</code></li><li>模型标识：<code>deepseek-ai/DeepSeek-V4-Pro</code> 或 <code>deepseek-ai/DeepSeek-V4-Flash</code></li><li>API 密钥：选择前面配置的硅基流动密钥</li></ul><p>具体模型可见硅基流动的 <a href="https://cloud.siliconflow.cn/me/models?target=deepseek-ai/DeepSeek-V4-Pro" target="_blank" rel="noreferrer">DeepSeek-V4-Pro</a> 和 <a href="https://cloud.siliconflow.cn/models?target=deepseek-ai/DeepSeek-V4-Flash" target="_blank" rel="noreferrer">DeepSeek-V4-Flash</a> 。</p>`,73)])])}const u=t(o,[["render",d]]);export{_ as __pageData,u as default};
